#!/usr/bin/env python3
"""gen_co2pipeline.py - independent reference corpus for co2pipeline.html (CoolProp HEOS CO2; forced NPS, no boosters; isothermal = T held at Tg per spec). Generated by Claude."""
import json, math, os
from CoolProp.CoolProp import PropsSI

FL = 'HEOS::CO2'
G = 9.80665
OD_IN = {6: 6.625, 8: 8.625, 10: 10.75, 12: 12.75}
SMYS = {'X52': 359e6, 'X56': 386e6, 'X60': 414e6, 'X65': 448e6, 'X70': 483e6}
DEF = dict(phase='dense', mdot=79.2, L=100e3, p_in=150e5, T_in=308.15, Tg=283.15, z1=0.0,
           p_min=90e5, MAOP=200e5, nps=16, grade='X65', thermal='U', U=2.0, offshore=False,
           allowOffshoreBoosters=False, maxBoosters=5, CA=0.001, eps=45e-6, elec=90,
           rate=0.08, life=25)


def friction(Re, eps, D):
    if Re < 2300:
        return 64.0 / Re
    f = 0.25 / math.log10(eps / (3.7 * D) + 5.74 / Re ** 0.9) ** 2
    for _ in range(30):
        f = (-2.0 * math.log10(eps / (3.7 * D) + 2.51 / (Re * math.sqrt(f)))) ** -2
    return f


def compute(i):
    OD = OD_IN.get(i['nps'], float(i['nps'])) * 0.0254
    F = 0.77 if i['offshore'] else 0.72
    t = max(i['MAOP'] * OD / (2 * F * SMYS[i['grade']] * 1.0) + i['CA'], 6.35e-3, OD / 72)
    t = math.ceil(t * 1e4 - 1e-9) / 1e4
    ID = OD - 2 * t
    A = math.pi * ID ** 2 / 4
    N = 2000
    dx, dz = i['L'] / N, i['z1'] / N
    mdot, iso = i['mdot'], i['thermal'] == 'isothermal'

    def inc(p, h, ddx, ddz):
        rho = PropsSI('D', 'P', p, 'H', h, FL)
        mu = PropsSI('V', 'P', p, 'H', h, FL)
        T = PropsSI('T', 'P', p, 'H', h, FL)
        v = mdot / (rho * A)
        f = friction(rho * v * ID / mu, i['eps'], ID)
        dp = f * ddx / ID * rho * v ** 2 / 2 + rho * G * ddz
        dh = 0.0 if iso else i['U'] * math.pi * OD * ddx * (i['Tg'] - T) / mdot - G * ddz
        return dp, dh, rho

    p = i['p_in']
    h = PropsSI('H', 'P', p, 'T', i['Tg'] if iso else i['T_in'], FL)
    lp = 0.0
    for _ in range(N):
        dp1, dh1, _r = inc(p, h, dx / 2, dz / 2)
        pm = p - dp1
        hm = PropsSI('H', 'P', pm, 'T', i['Tg'], FL) if iso else h + dh1
        dp2, dh2, rm = inc(pm, hm, dx, dz)
        p -= dp2
        h = PropsSI('H', 'P', p, 'T', i['Tg'], FL) if iso else h + dh2
        lp += rm * A * dx
    T_out = PropsSI('T', 'P', p, 'H', h, FL)
    capex = i['L'] * (250 + 55 * i['nps']) * (1.7 if i['offshore'] else 1.0)
    opex = capex * (0.015 if i['offshore'] else 0.01)
    r, n = i['rate'], i['life']
    crf = r * (1 + r) ** n / ((1 + r) ** n - 1)
    annual_t = mdot * 8760 * 3600 * 0.95 / 1000
    lcot = (capex * crf + opex) / annual_t
    if p < i['p_min']:
        raise RuntimeError('p_out below p_min: %s' % i)
    return dict(t=t, ID=ID, dp=i['p_in'] - p, p_out=p, T_out=T_out, linepack=lp,
                capex=capex, lcot=lcot)


CASES = [
    ('base_nps16', 'Dense base case NPS16', {}),
    ('nps14', 'Dense NPS14', dict(nps=14)),
    ('nps18', 'Dense NPS18', dict(nps=18)),
    ('nps20', 'Dense NPS20', dict(nps=20)),
    ('isothermal_nps16', 'Isothermal NPS16', dict(thermal='isothermal')),
    ('adiabatic_U0_nps16', 'U=0 (adiabatic) NPS16', dict(U=0.0)),
    ('uphill300_nps18', 'Elevation +300 m NPS18', dict(z1=300.0, nps=18)),
    ('downhill200_nps16', 'Elevation -200 m NPS16', dict(z1=-200.0)),
    ('offshore_nps16', 'Offshore NPS16 Tg 278.15', dict(offshore=True, MAOP=200e5, Tg=278.15)),
    ('x52_nps16', 'Grade X52 NPS16', dict(grade='X52')),
    ('x70_nps16', 'Grade X70 NPS16', dict(grade='X70')),
    ('short_nps12', 'L 50 km NPS12 mdot 30', dict(L=50e3, nps=12, mdot=30.0)),
    ('gas_nps16', 'Gas phase NPS16', dict(phase='gas', mdot=15.0, L=30e3, p_in=35e5,
                                         T_in=313.15, MAOP=40e5, p_min=20e5, nps=16,
                                         eps=45e-6)),
]


def main():
    out = []
    for cid, note, ov in CASES:
        inp = dict(DEF)
        inp.update(ov)
        out.append(dict(id=cid, note=note, inputs=inp, ref=compute(inp)))
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'co2pipeline_ref.json')
    with open(path, 'w') as fh:
        json.dump(out, fh, indent=2)
    print(len(out))


if __name__ == '__main__':
    main()
